const rows=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(rows.some(x=>x.error))return [{json:{mode:'READ_ONLY',status:'BLOCKED',reason:'DATA_TABLE_EVENTS_UNAVAILABLE',canSend:false}}];
if(rows.length>3000)throw new Error('TOO_MANY_LIGHTWEIGHT_EVENTS_USE_ROLLUPS');
const now=Date.now(),summary=new Map();let included=0;
for(const x of rows){
  const code=String(x.errorCode||'');
  const at=Date.parse(x.occurredAt);
  if(!/^[0-9]{5,6}$/.test(code)||!Number.isFinite(at)||at>now||now-at>30*86400000)continue;
  const count=x.count==null?1:Number(x.count);
  if(!Number.isSafeInteger(count)||count<0)throw new Error('INVALID_EVENT_AGGREGATE_COUNT');
  summary.set(code,(summary.get(code)||0)+count);included++;
}
const policies={
 '131050':'MARKETING_OPT_OUT_DO_NOT_AUTO_RETRY',
 '131048':'QUALITY_RESTRICTION_REVIEW_AND_PAUSE',
 '131049':'PER_RECIPIENT_MARKETING_HOLD_USE_EXISTING_CRM_RETRY',
 '131026':'UNDELIVERABLE_UNKNOWN_NOT_UNREGISTERED',
 '130472':'MARKETING_EXPERIMENT_REVIEW',
 '132015':'TEMPLATE_QUALITY_HOLD'
};
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',
 result:included?'AGGREGATED_RECORDED_EVENTS':'NO_RECENT_RECORDED_EVENTS',
 recordsIncluded:included,byCode:[...summary].map(([code,count])=>({code,count,policy:policies[code]||'REQUIRES_MANUAL_CLASSIFICATION'})),
 source:'AGE_Dispatcher_Events n8n Data Table; NOT an independently complete provider ledger',
 marketingSuppressionApplied:false,canSend:false}}];
